const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdEntries = [];
  let allThresholdsPassed = true;

  for (const [metricId, minScore] of Object.entries(thresholds)) {
    const metric = evaluations.find((m) => m.id === metricId);
    const score = metric?.score;
    const passed = score !== null && score !== undefined && score >= minScore;

    if (!passed) {
      allThresholdsPassed = false;
    }

    thresholdEntries.push({
      metric: metricId,
      min: minScore,
      score: score ?? null,
      passed
    });
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (Object.keys(thresholds).length > 0) {
    report.passed = allThresholdsPassed;
    report.thresholds = thresholdEntries;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export function parseThresholds(thresholdStrings = [], knownMetrics = null) {
  const thresholds = {};
  const DEFAULT_METRIC_IDS = ['exact_match', 'toxicity', 'length_variance'];
  const metricsToValidate = knownMetrics ?? DEFAULT_METRIC_IDS;

  for (const threshStr of thresholdStrings) {
    const match = threshStr.match(/^([a-zA-Z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(
        `Malformed threshold: "${threshStr}". Format must be <metric>=<number> (e.g., exact_match=0.9)`
      );
    }

    const [, metricId, scoreStr] = match;
    const score = Number.parseFloat(scoreStr);

    if (Number.isNaN(score) || score < 0 || score > 1) {
      throw new Error(
        `Invalid threshold value for "${metricId}": ${scoreStr}. Must be a number between 0 and 1.`
      );
    }

    if (knownMetrics === null && !metricsToValidate.includes(metricId)) {
      throw new Error(
        `Unknown metric: "${metricId}". Valid metrics are: ${metricsToValidate.join(', ')}`
      );
    }

    thresholds[metricId] = score;
  }

  return thresholds;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric,
  parseThresholds
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  parseThresholds,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

