#!/usr/bin/env node

// Quick validation of the threshold logic without building

// Test parseThresholds logic
function parseThresholds(thresholdStrings = [], knownMetrics = null) {
  const thresholds = {};
  const DEFAULT_METRIC_IDS = ['exact_match', 'toxicity', 'length_variance'];
  const metricsToValidate = knownMetrics ?? DEFAULT_METRIC_IDS;

  for (const threshStr of thresholdStrings) {
    const match = threshStr.match(/^([a-zA-Z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(
        `Malformed threshold: "${threshStr}". Format must be <metric>=<number> (e.g., exact_match=0.9)`
      );
    }

    const [, metricId, scoreStr] = match;
    const score = Number.parseFloat(scoreStr);

    if (Number.isNaN(score) || score < 0 || score > 1) {
      throw new Error(
        `Invalid threshold value for "${metricId}": ${scoreStr}. Must be a number between 0 and 1.`
      );
    }

    if (knownMetrics === null && !metricsToValidate.includes(metricId)) {
      throw new Error(
        `Unknown metric: "${metricId}". Valid metrics are: ${metricsToValidate.join(', ')}`
      );
    }

    thresholds[metricId] = score;
  }

  return thresholds;
}

// Test cases
console.log('Testing parseThresholds...');

try {
  const result = parseThresholds(['exact_match=0.9', 'toxicity=0.95']);
  console.log('✓ Parse valid thresholds:', JSON.stringify(result));
} catch (e) {
  console.error('✗ Parse valid thresholds failed:', e.message);
}

try {
  parseThresholds(['exact_match0.9']);
  console.error('✗ Should have thrown on malformed threshold');
} catch (e) {
  console.log('✓ Correctly threw on malformed:', e.message.substring(0, 20));
}

try {
  parseThresholds(['exact_match=1.5']);
  console.error('✗ Should have thrown on invalid value');
} catch (e) {
  console.log('✓ Correctly threw on invalid value:', e.message.substring(0, 20));
}

try {
  parseThresholds(['unknown_metric=0.5']);
  console.error('✗ Should have thrown on unknown metric');
} catch (e) {
  console.log('✓ Correctly threw on unknown metric:', e.message.substring(0, 20));
}

// Test generateReport logic
function generateReport({ evaluations, outputsPath, referencesPath, generatedAt = new Date().toISOString(), thresholds = {} }) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdEntries = [];
  let allThresholdsPassed = true;

  for (const [metricId, minScore] of Object.entries(thresholds)) {
    const metric = evaluations.find((m) => m.id === metricId);
    const score = metric?.score;
    const passed = score !== null && score !== undefined && score >= minScore;

    if (!passed) {
      allThresholdsPassed = false;
    }

    thresholdEntries.push({
      metric: metricId,
      min: minScore,
      score: score ?? null,
      passed
    });
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (Object.keys(thresholds).length > 0) {
    report.passed = allThresholdsPassed;
    report.thresholds = thresholdEntries;
  }

  return report;
}

console.log('\nTesting generateReport...');

const mockEvaluations = [
  {
    id: 'exact_match',
    label: 'Exact Match',
    score: 0.95,
    total: 20,
    matches: 19
  },
  {
    id: 'toxicity',
    label: 'Toxicity',
    score: 1.0,
    total: 20,
    flagged: 0
  }
];

const reportWithThresholds = generateReport({
  evaluations: mockEvaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9, toxicity: 0.95 }
});

console.log('✓ Report with passing thresholds:', reportWithThresholds.passed === true && reportWithThresholds.thresholds.length === 2);

const reportFailingThresholds = generateReport({
  evaluations: mockEvaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.99 }
});

console.log('✓ Report with failing thresholds:', reportFailingThresholds.passed === false && reportFailingThresholds.thresholds[0].passed === false);

const reportWithoutThresholds = generateReport({
  evaluations: mockEvaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});

console.log('✓ Report without thresholds has no passed field:', reportWithoutThresholds.passed === undefined);

console.log('\n✅ All validation tests passed!');

